313				margin: 0 0 1rem 0;
314				font-size: 0.875rem;
315				color: var(--text-secondary);
316			}
317			.field .form-hint {
318				margin: 0.25rem 0 0 0;
319			}
320			input:user-invalid,
321			textarea:user-invalid,
322			[aria-invalid="true"] {
323				border-color: var(--error);
324				box-shadow: inset 0 0 0 1px var(--error);
325			}
326			.error-message {
327				display: block;
328				color: var(--error);
329				font-size: 0.875rem;
330				font-weight: 500;
331				margin-top: 0.25rem;
332			}
333			.error-message:empty {
334				display: none;
335			}
