351			@media print {
352				:root {
353					color-scheme: light;
354					--text: #000;
355					--text-secondary: #333;
356					--background: #fff;
357					--surface: #fff;
358					--accent: #000;
359					--border: #999;
360					--border-control: #000;
361					--error: #000;
362				}
363				.skip-link,
364				nav,
365				button,
366				.button,
367				.live-region {
368					display: none;
