if (resetBtn) {
	resetBtn.addEventListener('click', () => {
		count = 0;
		updateCountDisplay();
	});
}

if (announceBtn) {
	announceBtn.addEventListener('click', () => {
		document.getElementById('live-message').textContent = messages[nextMessage];
		nextMessage = (nextMessage + 1) % messages.length;
	});
}

if (contactForm) {
	const emailError = document.getElementById('email-error');

	const validateEmail = () => {
		let message = '';
		if (emailInput.validity.valueMissing) {
			message = 'Enter your email address.';
		} else if (!emailInput.validity.valid) {
			message = 'Enter an email address in the format name@example.com.';
		}
		emailError.textContent = message;
		if (message) {
			emailInput.setAttribute('aria-invalid', 'true');
			emailInput.setAttribute('aria-describedby', 'email-error email-help');
		} else {
			emailInput.removeAttribute('aria-invalid');
			emailInput.setAttribute('aria-describedby', 'email-help');
		}
		return !message;
	};

	emailInput.addEventListener('blur', () => {
		if (emailInput.value || emailInput.hasAttribute('aria-invalid')) {
			validateEmail();
		}
	});
